public long repeatedString(String s, long n) {
    StringBuilder sb = new StringBuilder();
    while (sb.length() < n) {
        sb.append(s);
    }
    String prefix = sb.substring(0, (int) n);
    long count = 0;
    for (int i = 0; i < prefix.length(); i++) {
        if (prefix.charAt(i) == 'a') count++;
    }
    return count;
}

